import { AppbarContainer, AppShell } from '@app/ui';
import { EntitySettingsPageContainer, entityFinders } from '@droid/project-v2-ui';
import { IActionGroup } from '@droid/project-v2-interface';
import { useTranslation } from '@fanfanlo';

export default function ActionGroupSettings() {
    const { t } = useTranslation('homepage/pages/action-group-settings/content');
    return (
        <AppShell>
            <AppbarContainer appbarProps={{ title: t('content.title'), back: true }}>
                <EntitySettingsPageContainer<IActionGroup>
                    finder={entityFinders.actionGroup}
                    title={t('content.title')}
                />
            </AppbarContainer>
        </AppShell>
    );
}
