import React, { useState } from 'react';
import { IEntityBase } from '@droid/project-v2-interface';
import { Box, Paper, Button, AppBar, Toolbar, Typography, IconButton, Container } from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import SaveIcon from '@mui/icons-material/Save';
import { EntityBasicInfoEditor } from './EntityBasicInfoEditor';
import { useTranslation } from '@fanfanlo';

export interface EntitySettingsPageProps<T extends IEntityBase> {
    title: string;
    entity: T;
}

export function EntitySettingsPage<T extends IEntityBase>({
    title,
    entity
}: EntitySettingsPageProps<T>) {
    const { t } = useTranslation('droid-project-v2-ui/ui/components/entity-settings/content');

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', bgcolor: 'background.default' }}>
            {/* Content */}
            <Container maxWidth="md" sx={{ py: 4 }}>
                <Paper sx={{ p: 3, borderRadius: 2 }}>
                    <EntityBasicInfoEditor
                        entity={entity}
                        showTitle={true}  // 默认尝试显示
                        showSubtitle={true}
                        showTags={true}
                        showCategories={true}
                    />
                </Paper>
            </Container>
        </Box>
    );
}
